fresh('closure');run('pts={{100,20},{180,20},{150,80}};for _,o in ipairs{outline{pts=pts,seed=1},outline{pts=pts,open=true,seed=1},outline{pts=pts,closed=true,seed=1},outline{pts=pts,open=true,closed=true,seed=1}} do print(o.closed);print(pcall(function()return o:mask():area()end)) end;t=outline{pts={{100,20},{110,20},{110,30},{100,30}},amount=0}:inset(7);print(#t:paths(),t:mask():area());o=outline{pts=pts,seed=1};local p=o:path();print("ends",p[1][1],p[1][2],p[#p][1],p[#p][2],o.ramps[1],o.ramps[2]);op=outline{pts={{100,80},{800,80}},seed=1};print("sides",op:above():at(400,20),op:above():at(400,150),op:below():at(400,20),op:below():at(400,150))');cli('close')
